//
// Typically a max current or max power setpoint should reference a DC
// EVSE port, but not both.  Usually it is preferred to control a DC EVSE
// port using a max power setpoint.
DcEvsePort: EvsePort & ElecDcEquip

// A DC EVSE port with a single DC EVSE connector, modeled as one combined
// entity.  See [ph.doc::EVSE] chapter.
DcEvsePortConnector: DcEvsePort & DcEvseConnector

// Dedicated Outside Air System: An AHU that brings in 100% outside air and
// no recirculated air in order to provide ventilation to spaces.
// See [ph.doc::AHUs] chapter.
Doas: Ahu {
  doas
}

// Conduit used to convey air for HVAC
Duct: Conduit {
  duct
  ductDeck:    DuctDeck?
  ductSection: DuctSection?
}

// Electric equipment
ElecEquip: Equip {
  elec
}

// AC electric equipment
ElecAcEquip: ElecEquip {
  ac
}

// DC electric equipment
ElecDcEquip: ElecEquip {
  dc
}

// Electricity meter
ElecMeter: Meter {
  elec
}

// Physical housing for electrical circuits, fuses, and breakers.
// See [ph.doc::ElecPanels#elec-panel] chapter.
ElecPanel: Panel {
  elec
}

// Enclosure used to move people between floors.
Elevator: VerticalTransport {
  elevator
}

// Moving staircase used to move people between floors.
Escalator: VerticalTransport {
  escalator
}

// Plug, socket/receptacle, or wireless inductive charging pad that connects an EVSE to a vehicle inlet.
// The [ph::PhEntity.evseConnectorType] tag distinguishes the type of connector.
// See [ph.doc::EVSE#evse-connector] chapter.
EvseConnector: EvseEquip <abstract> {
  evseConnector
  evseConnectorType: EvseConnectorType?
}

// An [ph::EvseConnector] that delivers [ph::PhEntity.ac] electricity.
// See [ph.doc::EVSE#evse-connector] chapter.
AcEvseConnector: EvseConnector & ElecAcEquip

// An [ph::EvseConnector] that delivers [ph::PhEntity.dc] electricity.
// See [ph.doc::EVSE#evse-connector] chapter.
DcEvseConnector: EvseConnector & ElecDcEquip

// Equipment that dispenses electricity to an EV.  It consists of a
// physical EVSE enclosure and its contents to which an [ph::EvseConnector]
// attaches.  An [ph::EvseDispenser] can contain zero or more [ph::EvsePort].
//
// Children points are used to describe or control one or more [ph::EvsePort]
// within the EVSE manufacturer's package.
//
// See [ph.doc::EVSE#evse-dispenser] chapter.
EvseDispenser: EvseEquip {
  dispenser
}

// Equipment that supports the delivery of electricity to charging inlets
// located on EVs.  See [ph.doc::EVSE] chapter.
EvseEquip: ElecEquip {
  evse
}

// An EVSE port delivers electricity to a single EV charging inlet at a
// time.  Comprised of a software-controlled electrical contactor or
// circuit breaker.  Typically contained within an [ph::EvseDispenser], but
// may be contained within an [ph::EvsePowerConverter].  More than one
// [ph::EvseConnector] may be connected to a single [ph::EvsePort], however, only one
// may be energized at any given time.
//
// Note:  In the future we might add an entity that describes [ph::EvsePort]
// contained in an AC distribution panel.  This scenario is not common.
//
// See [ph.doc::EVSE#evse-port] chapter.
EvsePort: EvseEquip {
  port
}

// A power converter that has a [ph::PhEntity.dc] electrical output applied to a
// [ph::DcEvsePort].  May be contained within an [ph::EvseDispenser] or in a
// separate dedicated equipment enclosure.
//
// Children points are used to describe or control one or more [ph::EvsePort]
// within the EVSE manufacturer's package.
//
// See [ph.doc::EVSE#evse-power-converter] chapter.
EvsePowerConverter: EvseEquip {
