//////////////////////////////////////////////////////////////////////////
// Point Kinds
//////////////////////////////////////////////////////////////////////////

// Boolean or binary/digital point with an true/false state
BoolPoint : Point <abstract> {

  // Boolean points are required to have `"Bool"` kind
  kind: Kind <invariant> "Bool"

